button.clickEventHandler:
  var attachmentTitle = data.attachments.filter(function(attachment) {
    return attachment.group === "DocumentGroup";
  });
  var docName = "";
  attachmentTitle.forEach(attachment => {
    if (docName === "")
      docName = attachment.title
    else
      docName = docName + "; " + attachment.title
  })
  ESS.actions.facilityActions.runFacility({id: '5c85d154-09cd-4b64-84d1-37088a2107f3'}, {parameters: {ItemId: data.id, ItemName: data.name, DocName: docName}}, sender);

  var attachmentTitle = data.attachments.filter(function(attachment) {
    return attachment.group === "DocumentGroup";
  });
  var docName = "";
  attachmentTitle.forEach(attachment => {
    if (docName === "")
      docName = attachment.title
    else
      docName = docName + "; " + attachment.title
  })
  ESS.actions.facilityActions.runFacility({id:'d3f7270a-2680-44fe-b231-1708b532beb3'}, {parameters: {ItemId: data.id, ItemName: data.name, DocName: docName, StateName: 'ForRevision', IsSigned: true}}, sender);


  const certOverlayId = 'signDocument_getEmployeeCertificates';
  ESS.overlay.showOverlay(certOverlayId);
  
  ESS.network.sendRequest('/api/functions/GetEmployeeCertificates')
    .then(function(certs) {
      var documents = [];
      
      var documentGroups = data.attachments.filter(function(x) {
        return x.group === 'DocumentGroup' || x.group === 'AddendaGroup';
      });
      
      documentGroups.forEach(function(a) {
        documents.push({ id: a.id, title: a.title });
      });
      
      var allowSignSubstitution = data.requisites.find(function(_ref) {
        var name = _ref.name;
        return name === 'AllowSignSubstitution';
      }).value;
      
      var signatureType = allowSignSubstitution ? 'EmployerApproval' : 
        data.requisites.find(function(_ref) {
          var name = _ref.name;
          return name === 'SignatureType';
        }).value;
      
      function signDocuments() {
        return new Promise(function(resolve, reject) {
          ESS.network.sendRequest('/api/functions/IsAssignmentCardBlocked?assignmentId=' + data.id)
            .then(function(message) {
              if (!message) {
                ESS.signing.sign({
                  certificates: certs,
                  documents: documents,
                  documentGroup: 'IElectronicDocuments',
                  systemName: data.system,
                  signatureType: signatureType,
                  packageTitle: data.title,
                  signedBy: data.performer,
                  callback: function() {
                    resolve();
                  },
                  errorCallback: function(err) {
                    reject(err);
                  }
                });
              } else {
                reject(new Error(message));
              }
            })
            .catch(function(err) {
              reject(err);
            })
            .finally(function() {
              ESS.overlay.hideOverlay(certOverlayId);
            });
        });
      }
      
      function getVacationInfo() {
        return new Promise(function(resolve) {
          ESS.network.sendRequest('/api/functions/GetVacationInfoByAssignmentId?assignmentId=' + data.id)
            .then(function(response) {
              if (!response) {
                resolve({ vacationKindId: 0, periods: [] });
                return;
              }
              var vacationKindId = response.vacationKindId || response.VacationKindId || 0;
              var rawPeriods = response.periods || response.Periods || [];
              
              var normalizedPeriods = rawPeriods.map(function(p) {
                return {
                  StartDate: p.startDate || p.StartDate,
                  EndDate: p.endDate || p.EndDate
                };
              });
              resolve({
                vacationKindId: vacationKindId,
                periods: normalizedPeriods
              });
            })
            .catch(function(error) {
              resolve({ vacationKindId: 0, periods: [] });
            });
        });
      }
      
      function openSubstitutionFacility(vacationData) {
        return new Promise(function(resolve) {
          var periods = vacationData.periods;
          var vacationKindId = vacationData.vacationKindId;
          
          if (!periods || periods.length === 0) {
            resolve(false);
            return;
          }
          
          var vacationPeriodsJson = JSON.stringify(periods);
          
          ESS.actions.facilityActions.runFacility(
            { id: '2a5f2cfc-8646-4bb8-920c-a985b15da804' },
            {
              parameters: {
                InitiatorId: data.performer,
                AssignmentId: data.id,
                AssignmentType: data.name,
                VacationPeriodsJson: vacationPeriodsJson,
                CompleteAssignmentAfterSubmit: true,
                WorkItemChangingReason: 'Sign',
                VacationKindId: vacationKindId
              }
            }
          );
          resolve(true);
        });
      }
      
      function completeAssignmentDirectly() {
        const overlayId = 'signDocument_changeWorkItemState';
        ESS.overlay.showOverlay(overlayId);
        
        return ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Sign')
          .then(function() {
            ESS.closeElement(sender);
            ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.OBJECTCARD_FACILITY_SUCCESSMESSAGE'), 'success', true);
            ESS.widgets.updateWidgets();
          })
          .catch(function(error) {
            ESS.toasts.showErrorToastWithLog(ESS.L('@HRPROSTATEMENTS.ERR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
          })
          .finally(function() {
            ESS.overlay.hideOverlay(overlayId);
          });
      }
      
      signDocuments()
        .then(function() {
          return getVacationInfo();
        })
        .then(function(vacationInfo) {
          return openSubstitutionFacility(vacationInfo);
        })
        .then(function(facilityOpened) {
          if (!facilityOpened) {
            return completeAssignmentDirectly();
          }
          ESS.closeElement(sender);
          ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.OBJECTCARD_FACILITY_SUCCESSMESSAGE'), 'success', true);
          ESS.widgets.updateWidgets();
        })
        .catch(function(error) {
          ESS.toasts.showErrorToastWithLog('Ошибка при подписании', error.message);
          ESS.overlay.hideOverlay(certOverlayId);
        });
        
    })
    .catch(function(err) {
      ESS.overlay.hideOverlay(certOverlayId);
      ESS.toasts.showErrorToastWithLog(err);
    });

objectCard.openedEventHandler:
   
      if(data.requisites.find(re => re.name === "CanSign").value === false ||
        data.requisites.find(re => re.name == "CanSign").value === null)
        configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Sign"), 1);

      if(data.requisites.find(re => re.name === "CanForRevision").value === false ||
          data.requisites.find(re => re.name == "CanForRevision").value === null)
        configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Rework"), 1);

      if(data.requisites.find(re => re.name === "CanRefuse").value === false ||
        data.requisites.find(re => re.name == "CanRefuse").value === null)
        configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Refuse"), 1);
        
        var isSubstitutionAllowed = data.requisites.find(re => re.name == "IsSubstitutionAllowedDirRX").value ?? true;
        ESS.network.sendRequest(`/api/functions/CheckIfCurrentUserIsPerformer?personId=$(CurrentUser.DirectumRX.PersonId)&assignmentId=${data.id}`)
        .then(function (isPerformer){
          if (!isPerformer){
            if (!isSubstitutionAllowed){
              data.isSubstitutionNotAllowedMessage = ESS.L('@HRPROSTATEMENTS.SUBSTITUTION_NOT_ALLOWED');
              data.isSubstitutionAllowed = isSubstitutionAllowed;
              functions.setVisibility(['Refuse', 'Rework', 'Sign'], ESS.enums.Visibility.HIDDEN);
            }
          }
        })
      
      ESS.network.sendRequest(`/api/functions/GetTaskActiveText?assignmentId=${data.id}`)
      .then(function (activeText){
        data.comment = activeText.replace(/([\r\n])/g, '<br/>');
        resolve({configuration: configuration, data: data});
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, 'danger', false);
        reject();
      });
